WITH filtered AS (SELECT *, CAST(event_time AS DATE) AS event_time_day FROM web_events WHERE duration_sec = 340) SELECT CASE WHEN duration_sec >= 516 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_tier, SORT_ARRAY(COLLECT_SET(page)) AS page_list, PERCENTILE_APPROX(duration_sec, ARRAY(0.25, 0.5, 0.75)) AS duration_sec_quartiles, SUM(CASE WHEN page = '/search' THEN duration_sec ELSE 0 END) AS search_duration_sec, AVG(duration_sec) AS avg_duration_sec FROM filtered GROUP BY CASE WHEN duration_sec >= 516 THEN 'PREMIUM' ELSE 'STANDARD' END;
